package pt.isel
import kotlinx.datetime.LocalDate import org.jdbi.v3.core.Handle import pt.isel.payment.Charge import pt.isel.payment.ChargeStatus import pt.isel.payment.ChargeType import java.sql.ResultSet
class JdbiChargeRepository(private val handle: Handle) : ChargeRepository {
private fun mapRow(rs: ResultSet): Charge { val memberIdObj = rs.getObject("member_id") val sponsorshipIdObj = rs.getObject("sponsorship_id") val monthObj = rs.getObject("month")
return Charge( chargeId = rs.getLong("charge_id"), type = ChargeType.valueOf(rs.getString("type")), memberId = if (rs.wasNull() || memberIdObj == null) null else (memberIdObj as Number).toLong(), sponsorshipId = if (sponsorshipIdObj == null) null else (sponsorshipIdObj as Number).toLong(), value = rs.getDouble("value"), status = ChargeStatus.valueOf(rs.getString("status")), season = rs.getString("season"), month = if (monthObj == null) null else (monthObj as Number).toInt(), createdAt = LocalDate.parse(rs.getString("created_at")), paidAt = rs.getString("paid_at")?.let { LocalDate.parse(it) } ) }
override fun findById(id: Long): Charge? { return handle.createQuery("SELECT * FROM charge WHERE charge_id = :id") .bind("id", id) .map { rs, _ -> mapRow(rs) } .findOne() .orElse(null) }
override fun findByMemberAndSeason(memberId: Long, season: String): List<Charge> { return handle.createQuery("SELECT * FROM charge WHERE member_id = :memberId AND season = :season ORDER BY month ASC") .bind("memberId", memberId) .bind("season", season) .map { rs, _ -> mapRow(rs) } .list() }
override fun findPendingByMember(memberId: Long): List<Charge> { return handle.createQuery("SELECT * FROM charge WHERE member_id = :memberId AND status = 'PENDING' ORDER BY created_at ASC") .bind("memberId", memberId) .map { rs, _ -> mapRow(rs) } .list() }
override fun existsByMemberSeasonMonth(memberId: Long, season: String, month: Int): Boolean { return handle.createQuery("SELECT COUNT(*) FROM charge WHERE member_id = :memberId AND season = :season AND month = :month") .bind("memberId", memberId) .bind("season", season) .bind("month", month) .mapTo(Int::class.java) .one() > 0 }
override fun save(charge: Charge): Long { return handle.createUpdate( """ INSERT INTO charge (type, member_id, sponsorship_id, value, status, season, month, created_at, paid_at) VALUES (CAST(:type AS charge_type), :memberId, :sponsorshipId, :value, CAST(:status AS charge_status), :season, :month, CAST(:createdAt AS DATE), CAST(:paidAt AS DATE)) """ ) .bind("type", charge.type.name) .bind("memberId", charge.memberId) .bind("sponsorshipId", charge.sponsorshipId) .bind("value", charge.value) .bind("status", charge.status.name) .bind("season", charge.season) .bind("month", charge.month) .bind("createdAt", charge.createdAt.toString()) .bind("paidAt", charge.paidAt?.toString()) .executeAndReturnGeneratedKeys() .mapTo(Long::class.java) .one() }
override fun update(charge: Charge) { handle.createUpdate( """ UPDATE charge SET type = CAST(:type AS charge_type), member_id = :memberId, sponsorship_id = :sponsorshipId, value = :value, status = CAST(:status AS charge_status), season = :season, month = :month, created_at = CAST(:createdAt AS DATE), paid_at = CAST(:paidAt AS DATE) WHERE charge_id = :id """ ) .bind("id", charge.chargeId) .bind("type", charge.type.name) .bind("memberId", charge.memberId) .bind("sponsorshipId", charge.sponsorshipId) .bind("value", charge.value) .bind("status", charge.status.name) .bind("season", charge.season) .bind("month", charge.month) .bind("createdAt", charge.createdAt.toString()) .bind("paidAt", charge.paidAt?.toString()) .execute() } }

