package pt.isel
import kotlinx.datetime.LocalDate import org.jdbi.v3.core.Handle import pt.isel.member.Member import pt.isel.member.MemberCategory import pt.isel.member.MemberStatus import java.sql.ResultSet
class JdbiMemberRepository(private val handle: Handle) : MemberRepository {
private fun mapRow(rs: ResultSet): Member { val memberNumberObj = rs.getObject("member_number")
return Member( memberId = rs.getLong("member_id"), memberNumber = if (rs.wasNull() || memberNumberObj == null) 0 else (memberNumberObj as Number).toInt(), completeName = rs.getString("complete_name"), birthDate = LocalDate.parse(rs.getString("birth_date")), email = rs.getString("email"), phone = rs.getString("phone"), homePhone = rs.getString("home_phone"), address = rs.getString("address"), postalCode = rs.getString("postal_code"), city = rs.getString("city"), category = MemberCategory.valueOf(rs.getString("category")), status = MemberStatus.valueOf(rs.getString("status")), formerMember = rs.getBoolean("former_member"), monthlyQuota = rs.getDouble("monthly_quota"), billingLocation = rs.getString("billing_location"), registrationDate = LocalDate.parse(rs.getString("registration_date")), approvalDate = rs.getString("approval_date")?.let { LocalDate.parse(it) }, privacyAccepted = rs.getBoolean("privacy_accepted"), comsAccepted = rs.getBoolean("coms_accepted") ) }
override fun findById(id: Long): Member? { return handle.createQuery("SELECT * FROM member WHERE member_id = :id") .bind("id", id) .map { rs, _ -> mapRow(rs) } .findOne() .orElse(null) }
override fun findByEmail(email: String): Member? { return handle.createQuery("SELECT * FROM member WHERE email = :email") .bind("email", email) .map { rs, _ -> mapRow(rs) } .findOne() .orElse(null) }
override fun findAll(): List<Member> { return handle.createQuery("SELECT * FROM member ORDER BY member_number ASC") .map { rs, _ -> mapRow(rs) } .list() }
override fun findAllActive(): List<Member> { return handle.createQuery("SELECT * FROM member WHERE status = 'ATIVO' ORDER BY member_number ASC") .map { rs, _ -> mapRow(rs) } .list() }
override fun nextMemberNumber(): Int { val maxNumber = handle.createQuery("SELECT MAX(member_number) FROM member WHERE member_number IS NOT NULL") .mapTo(Int::class.javaObjectType) .findOne() .orElse(0) return (maxNumber ?: 0) + 1 }
override fun save(member: Member): Long { return handle.createUpdate( """ INSERT INTO member ( member_number, complete_name, birth_date, email, phone, home_phone, address, postal_code, city, category, status, former_member, monthly_quota, billing_location, registration_date, approval_date, privacy_accepted, coms_accepted ) VALUES ( :memberNumber, :completeName, CAST(:birthDate AS DATE), :email, :phone, :homePhone, :address, :postalCode, :city, CAST(:category AS member_category), CAST(:status AS member_status), :formerMember, :monthlyQuota, :billingLocation, CAST(:registrationDate AS DATE), CAST(:approvalDate AS DATE), :privacyAccepted, :comsAccepted ) """ ) .bind("memberNumber", if (member.memberNumber > 0) member.memberNumber else null) .bind("completeName", member.completeName) .bind("birthDate", member.birthDate.toString()) .bind("email", member.email) .bind("phone", member.phone) .bind("homePhone", member.homePhone) .bind("address", member.address) .bind("postalCode", member.postalCode) .bind("city", member.city) .bind("category", member.category.name) .bind("status", member.status.name) .bind("formerMember", member.formerMember) .bind("monthlyQuota", member.monthlyQuota) .bind("billingLocation", member.billingLocation) .bind("registrationDate", member.registrationDate.toString()) .bind("approvalDate", member.approvalDate?.toString()) .bind("privacyAccepted", member.privacyAccepted) .bind("comsAccepted", member.comsAccepted) .executeAndReturnGeneratedKeys() .mapTo(Long::class.java) .one() }
override fun update(member: Member) { handle.createUpdate( """ UPDATE member SET member_number = :memberNumber, complete_name = :completeName, birth_date = CAST(:birthDate AS DATE), email = :email, phone = :phone, home_phone = :homePhone, address = :address, postal_code = :postalCode, city = :city, category = CAST(:category AS member_category), status = CAST(:status AS member_status), former_member = :formerMember, monthly_quota = :monthlyQuota, billing_location = :billingLocation, registration_date = CAST(:registrationDate AS DATE), approval_date = CAST(:approvalDate AS DATE), privacy_accepted = :privacyAccepted, coms_accepted = :comsAccepted WHERE member_id = :id """ ) .bind("id", member.memberId) .bind("memberNumber", if (member.memberNumber > 0) member.memberNumber else null) .bind("completeName", member.completeName) .bind("birthDate", member.birthDate.toString()) .bind("email", member.email) .bind("phone", member.phone) .bind("homePhone", member.homePhone) .bind("address", member.address) .bind("postalCode", member.postalCode) .bind("city", member.city) .bind("category", member.category.name) .bind("status", member.status.name) .bind("formerMember", member.formerMember) .bind("monthlyQuota", member.monthlyQuota) .bind("billingLocation", member.billingLocation) .bind("registrationDate", member.registrationDate.toString()) .bind("approvalDate", member.approvalDate?.toString()) .bind("privacyAccepted", member.privacyAccepted) .bind("comsAccepted", member.comsAccepted) .execute() } }

