package pt.isel

import kotlinx.datetime.Instant
import org.jdbi.v3.core.Handle
import pt.isel.user.PasswordValidationInfo
import pt.isel.user.Role
import pt.isel.user.Token
import pt.isel.user.TokenValidationInfo
import pt.isel.user.User
import java.sql.ResultSet

class JdbiUserRepository(private val handle: Handle) : UserRepository {

    private fun mapUserRow(rs: ResultSet): User {
        val activeMemberIdObj = rs.getObject("active_member_id")
        return User(
            userId = rs.getLong("user_id"),
            email = rs.getString("email"),
            username = rs.getString("username"),
            passwordValidation = PasswordValidationInfo(rs.getString("password_validation")),
            role = Role.valueOf(rs.getString("role")),
            activeMemberId = if (activeMemberIdObj == null) null else (activeMemberIdObj as Number).toLong()
        )
    }

    override fun save(user: User): Long {
        return handle.createUpdate(
            """
            INSERT INTO users (email, username, password_validation, role, active_member_id)
            VALUES (:email, :username, :passwordValidation, CAST(:role AS user_role), :activeMemberId)
            """
        )
            .bind("email", user.email)
            .bind("username", user.username)
            .bind("passwordValidation", user.passwordValidation.validationInfo)
            .bind("role", user.role.name)
            .bind("activeMemberId", user.activeMemberId)
            .executeAndReturnGeneratedKeys()
            .mapTo(Long::class.java)
            .one()
    }

    override fun updatePassword(userId: Long, newPassword: PasswordValidationInfo) {
        handle.createUpdate("UPDATE users SET password_validation = :pw WHERE user_id = :id")
            .bind("pw", newPassword.validationInfo)
            .bind("id", userId)
            .execute()
    }

    override fun findById(id: Long): User? {
        return handle.createQuery("SELECT * FROM users WHERE user_id = :id")
            .bind("id", id)
            .map { rs, _ -> mapUserRow(rs) }
            .findOne()
            .orElse(null)
    }

    override fun findByUsername(username: String): User? {
        return handle.createQuery("SELECT * FROM users WHERE username = :username")
            .bind("username", username)
            .map { rs, _ -> mapUserRow(rs) }
            .findOne()
            .orElse(null)
    }

    override fun findByEmail(email: String): User? {
        return handle.createQuery("SELECT * FROM users WHERE email = :email")
            .bind("email", email)
            .map { rs, _ -> mapUserRow(rs) }
            .findOne()
            .orElse(null)
    }

    override fun update(user: User) {
        handle.createUpdate(
            """
            UPDATE users SET 
                email = :email, 
                username = :username, 
                password_validation = :passwordValidation, 
                role = CAST(:role AS user_role), 
                active_member_id = :activeMemberId
            WHERE user_id = :id
            """
        )
            .bind("id", user.userId)
            .bind("email", user.email)
            .bind("username", user.username)
            .bind("passwordValidation", user.passwordValidation.validationInfo)
            .bind("role", user.role.name)
            .bind("activeMemberId", user.activeMemberId)
            .execute()
    }

    override fun createToken(token: Token) {
        handle.createUpdate(
            """
            INSERT INTO user_token (token_validation, user_id, created_at, last_used_at)
            VALUES (:validation, :userId, CAST(:createdAt AS TIMESTAMP), CAST(:lastUsedAt AS TIMESTAMP))
            """
        )
            .bind("validation", token.tokenValidationInfo.validationInfo)
            .bind("userId", token.userId)
            .bind("createdAt", token.createdAt.toString())
            .bind("lastUsedAt", token.lastUsedAt.toString())
            .execute()
    }

    override fun getTokenByValidation(validation: TokenValidationInfo): Pair<User, Token>? {
        val userWithToken = handle.createQuery(
            """
            SELECT u.*, t.token_validation, t.created_at, t.last_used_at 
            FROM users u
            JOIN user_token t ON u.user_id = t.user_id
            WHERE t.token_validation = :validation
            """
        )
            .bind("validation", validation.validationInfo)
            .map { rs, _ ->
                val user = mapUserRow(rs)
                val token = Token(
                    tokenValidationInfo = TokenValidationInfo(rs.getString("token_validation")),
                    userId = rs.getLong("user_id"),
                    createdAt = Instant.parse(rs.getString("created_at").replace(" ", "T")),
                    lastUsedAt = Instant.parse(rs.getString("last_used_at").replace(" ", "T"))
                )
                Pair(user, token)
            }
            .findOne()

        return userWithToken.orElse(null)
    }

    override fun updateTokenLastUsed(token: Token, now: Instant) {
        handle.createUpdate("UPDATE user_token SET last_used_at = CAST(:now AS TIMESTAMP) WHERE token_validation = :validation")
            .bind("now", now.toString())
            .bind("validation", token.tokenValidationInfo.validationInfo)
            .execute()
    }

    override fun removeTokenByValidation(validation: TokenValidationInfo): Int {
        return handle.createUpdate("DELETE FROM user_token WHERE token_validation = :validation")
            .bind("validation", validation.validationInfo)
            .execute()
    }
}

package pt.isel

import kotlinx.datetime.Instant
import org.jdbi.v3.core.Handle
import pt.isel.mappers.TokenMapper
import pt.isel.mappers.UserMapper
import pt.isel.user.PasswordValidationInfo
import pt.isel.user.Token
import pt.isel.user.TokenValidationInfo
import pt.isel.user.User

class JdbiUserRepository(private val handle: Handle) : UserRepository {

    override fun save(user: User): Long {
        return handle.createUpdate(
            """
            INSERT INTO users (email, username, password_validation, role, active_member_id)
            VALUES (:email, :username, :passwordValidation, CAST(:role AS user_role), :activeMemberId)
            """
        )
            .bind("email", user.email)
            .bind("username", user.username)
            .bind("passwordValidation", user.passwordValidation.validationInfo)
            .bind("role", user.role.name)
            .bind("activeMemberId", user.activeMemberId)
            .executeAndReturnGeneratedKeys()
            .mapTo(Long::class.java)
            .one()
    }

    override fun updatePassword(userId: Long, newPassword: PasswordValidationInfo) {
        handle.createUpdate("UPDATE users SET password_validation = :pw WHERE user_id = :id")
            .bind("pw", newPassword.validationInfo)
            .bind("id", userId)
            .execute()
    }

    override fun findById(id: Long): User? {
        return handle.createQuery("SELECT * FROM users WHERE user_id = :id")
            .bind("id", id)
            .map { rs, _ -> UserMapper.map(rs) }
            .findOne()
            .orElse(null)
    }

    override fun findByUsername(username: String): User? {
        return handle.createQuery("SELECT * FROM users WHERE username = :username")
            .bind("username", username)
            .map { rs, _ -> UserMapper.map(rs) }
            .findOne()
            .orElse(null)
    }

    override fun findByEmail(email: String): User? {
        return handle.createQuery("SELECT * FROM users WHERE email = :email")
            .bind("email", email)
            .map { rs, _ -> UserMapper.map(rs) }
            .findOne()
            .orElse(null)
    }

    override fun update(user: User) {
        handle.createUpdate(
            """
            UPDATE users SET 
                email = :email, 
                username = :username, 
                password_validation = :passwordValidation, 
                role = CAST(:role AS user_role), 
                active_member_id = :activeMemberId
            WHERE user_id = :id
            """
        )
            .bind("id", user.userId)
            .bind("email", user.email)
            .bind("username", user.username)
            .bind("passwordValidation", user.passwordValidation.validationInfo)
            .bind("role", user.role.name)
            .bind("activeMemberId", user.activeMemberId)
            .execute()
    }

    override fun createToken(token: Token) {
        handle.createUpdate(
            """
            INSERT INTO user_token (token_validation, user_id, created_at, last_used_at)
            VALUES (:validation, :userId, CAST(:createdAt AS TIMESTAMP), CAST(:lastUsedAt AS TIMESTAMP))
            """
        )
            .bind("validation", token.tokenValidationInfo.validationInfo)
            .bind("userId", token.userId)
            .bind("createdAt", token.createdAt.toString())
            .bind("lastUsedAt", token.lastUsedAt.toString())
            .execute()
    }

    override fun getTokenByValidation(validation: TokenValidationInfo): Pair<User, Token>? {
        val userWithToken = handle.createQuery(
            """
            SELECT u.*, t.token_validation, t.created_at, t.last_used_at 
            FROM users u
            JOIN user_token t ON u.user_id = t.user_id
            WHERE t.token_validation = :validation
            """
        )
            .bind("validation", validation.validationInfo)
            .map { rs, _ ->
                val user = UserMapper.map(rs)
                val token = TokenMapper.map(rs)
                Pair(user, token)
            }
            .findOne()

        return userWithToken.orElse(null)
    }

    override fun updateTokenLastUsed(token: Token, now: Instant) {
        handle.createUpdate("UPDATE user_token SET last_used_at = CAST(:now AS TIMESTAMP) WHERE token_validation = :validation")
            .bind("now", now.toString())
            .bind("validation", token.tokenValidationInfo.validationInfo)
            .execute()
    }

    override fun removeTokenByValidation(validation: TokenValidationInfo): Int {
        return handle.createUpdate("DELETE FROM user_token WHERE token_validation = :validation")
            .bind("validation", validation.validationInfo)
            .execute()
    }
}

