package pt.isel.mappers
import kotlinx.datetime.LocalDateTime import pt.isel.payment.Payment import pt.isel.payment.PaymentStatus import java.sql.ResultSet
object PaymentMapper { fun map(rs: ResultSet): Payment = Payment( paymentId = rs.getLong("payment_id"), chargeId = rs.getLong("charge_id"), amount = rs.getDouble("amount"), provider = rs.getString("provider"), providerRef = rs.getString("provider_ref"), status = PaymentStatus.valueOf(rs.getString("status")), createdAt = LocalDateTime.parse(rs.getString("created_at").replace(" ", "T")), confirmedAt = rs.getString("confirmed_at")?.let { LocalDateTime.parse(it.replace(" ", "T")) }, ) }

package pt.isel.mappers
import pt.isel.sponsor.Sponsor import java.sql.ResultSet
object SponsorMapper { fun map(rs: ResultSet): Sponsor = Sponsor( sponsorId = rs.getLong("sponsor_id"), name = rs.getString("name"), email = rs.getString("email"), phone = rs.getString("phone"), nif = rs.getString("nif"), ) }

package pt.isel.mappers
import pt.isel.sponsor.EquipmentPlacement import pt.isel.sponsor.OtherSport import pt.isel.sponsor.PubOption import pt.isel.sponsor.SponsorType import pt.isel.sponsor.Sponsorship import pt.isel.sponsor.SponsorshipStatus import pt.isel.sponsor.TeamCategory import java.sql.ResultSet
object SponsorshipMapper { fun map(rs: ResultSet): Sponsorship = Sponsorship( sponsorshipId = rs.getLong("sponsorship_id"), sponsorId = rs.getLong("sponsor_id"), season = rs.getString("season"), status = SponsorshipStatus.valueOf(rs.getString("status")), type = SponsorType.valueOf(rs.getString("type")), price = rs.getDouble("price"), pubOption = rs.getString("pub_option")?.let(PubOption::valueOf), teamCategory = rs.getString("team_category")?.let(TeamCategory::valueOf), placement = rs.getString("placement")?.let(EquipmentPlacement::valueOf), sport = rs.getString("sport")?.let(OtherSport::valueOf), ) }

package pt.isel.mappers

import kotlinx.datetime.LocalDateTime
import pt.isel.event.Ticket
import java.sql.ResultSet

object TicketMapper {
    fun map(rs: ResultSet): Ticket {
        val memberId = (rs.getObject("member_id") as? Number)?.toLong()

        return Ticket(
            ticketId = rs.getLong("ticket_id"),
            memberId = memberId,
            buyerEmail = rs.getString("buyer_email"),
            buyerName = rs.getString("buyer_name"),
            eventId = rs.getLong("event_id"),
            price = rs.getDouble("price"),
            qrCode = rs.getString("qr_code"),
            used = rs.getBoolean("used"),
            usedAt = rs.getString("used_at")?.let { LocalDateTime.parse(it.replace(" ", "T")) },
        )
    }
}

package pt.isel.mappers
import kotlinx.datetime.Instant import pt.isel.user.Token import pt.isel.user.TokenValidationInfo import java.sql.ResultSet
object TokenMapper { fun map(rs: ResultSet): Token = Token( tokenValidationInfo = TokenValidationInfo(rs.getString("token_validation")), userId = rs.getLong("user_id"), createdAt = Instant.parse(rs.getString("created_at").replace(" ", "T")), lastUsedAt = Instant.parse(rs.getString("last_used_at").replace(" ", "T")), ) }

package pt.isel.mappers

import pt.isel.user.PasswordValidationInfo
import pt.isel.user.Role
import pt.isel.user.User
import java.sql.ResultSet

object UserMapper {
    fun map(rs: ResultSet): User {
        val activeMemberId = (rs.getObject("active_member_id") as? Number)?.toLong()

        return User(
            userId = rs.getLong("user_id"),
            email = rs.getString("email"),
            username = rs.getString("username"),
            passwordValidation = PasswordValidationInfo(rs.getString("password_validation")),
            role = Role.valueOf(rs.getString("role")),
            activeMemberId = activeMemberId,
        )
    }
}
